import org.junit.jupiter.api.Test;

class ExtensionInputScopeEvaluationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final Value SIBLING_VALUE = VF.createLiteral("sibling");
	private static final Value ROW_VALUE = VF.createLiteral("row");
	private static final Value CALLER_VALUE = VF.createLiteral("caller");

	@Test
	void unboundBindObservationDoesNotBecomeAMandatoryParameterAcrossIndependentDistinct() {
		Join query = new Join(values("sibling", binding("sibling", SIBLING_VALUE)),
				bindAfterPartiallyBoundDistinct("sibling"));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(query,
				EmptyBindingSet.getInstance());

		assertThat(analysis.canReceiveSiblingBindings(query.getRightArg(), query.getLeftArg().getBindingNames(),
				analysis.contextAt(query))).isFalse();

		PreparedQuery raw = prepareWithoutOptimization(query);
		assertThat(outerJoin(raw.expression()).getAlgorithmName())
				.isEqualTo(HashJoinIteration.class.getSimpleName());
		assertIndependentRows(evaluate(raw, EmptyBindingSet.getInstance()), false);

		PreparedQuery prepared = optimizeAndPrepare(query, EmptyBindingSet.getInstance());
		outerJoin(prepared.expression());
		assertIndependentRows(evaluate(prepared, EmptyBindingSet.getInstance()), false);
	}

	@Test
	void independentBindCanStillReadAnEntryBinding() {
		Join query = new Join(values("sibling", binding("sibling", SIBLING_VALUE)),
				bindAfterPartiallyBoundDistinct("entry", true));
		BindingSet entry = binding("entry", CALLER_VALUE);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(query, entry);

		assertThat(analysis.canReceiveSiblingBindings(query.getRightArg(), query.getLeftArg().getBindingNames(),
				analysis.contextAt(query))).isFalse();

		PreparedQuery raw = prepareWithoutOptimization(query);
		assertThat(outerJoin(raw.expression()).getAlgorithmName())
				.isEqualTo(HashJoinIteration.class.getSimpleName());
		assertIndependentRows(evaluate(raw, entry), true);

		PreparedQuery prepared = optimizeAndPrepare(query, entry);
		outerJoin(prepared.expression());
		assertIndependentRows(evaluate(prepared, entry), true);
	}

	@Test
	void distinctUnitDoesNotMakeAnUnboundBindReadIndependent() {
		Extension bindMissing = new Extension(new Distinct(new SingletonSet()),
				new ExtensionElem(Var.of("missing"), "derived"));
		Join query = new Join(values("sibling", binding("sibling", SIBLING_VALUE)), bindMissing);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(query,
				EmptyBindingSet.getInstance());

		assertThat(analysis.canReceiveSiblingBindings(query.getRightArg(), query.getLeftArg().getBindingNames(),
				analysis.contextAt(query))).isTrue();

		PreparedQuery raw = prepareWithoutOptimization(query);
		assertThat(outerJoin(raw.expression()).getAlgorithmName())
				.isEqualTo(JoinIterator.class.getSimpleName());
		List<BindingSet> rawRows = evaluate(raw, EmptyBindingSet.getInstance());
		assertThat(rawRows).hasSize(1);
		assertThat(rawRows.getFirst().getValue("sibling")).isEqualTo(SIBLING_VALUE);
		assertThat(rawRows.getFirst().hasBinding("derived")).isFalse();

		PreparedQuery prepared = optimizeAndPrepare(query, EmptyBindingSet.getInstance());
		assertThat(outerJoin(prepared.expression()).getAlgorithmName())
				.isEqualTo(JoinIterator.class.getSimpleName());
		List<BindingSet> actual = evaluate(prepared, EmptyBindingSet.getInstance());

		assertThat(actual).hasSize(1);
		assertThat(actual.getFirst().getValue("sibling")).isEqualTo(SIBLING_VALUE);
		assertThat(actual.getFirst().hasBinding("derived")).isFalse();
	}

	private static Extension bindAfterPartiallyBoundDistinct(String sourceName) {
		return bindAfterPartiallyBoundDistinct(sourceName, false);
	}

	private static Extension bindAfterPartiallyBoundDistinct(String sourceName, boolean observeSibling) {
		TupleExpr rows = new Distinct(new Union(
				values("row", binding("row", ROW_VALUE)), new SingletonSet()));
		if (observeSibling) {
			return new Extension(rows, new ExtensionElem(Var.of(sourceName), "derived"),
					new ExtensionElem(Var.of("sibling"), "derivedFromSibling"));
		}
		return new Extension(rows, new ExtensionElem(Var.of(sourceName), "derived"));
	}

	private static BindingSetAssignment values(String name, BindingSet row) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of(name));
		values.setBindingSets(List.of(row));
		return values;
	}

	private static QueryBindingSet binding(String name, Value value) {
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.addBinding(name, value);
		return bindings;
	}

	private static PreparedQuery optimizeAndPrepare(TupleExpr query, BindingSet input) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		TupleExpr optimized = strategy.optimize(new QueryRoot(query.clone()), new EvaluationStatistics(), input);
		return new PreparedQuery(optimized, strategy.precompile(optimized));
	}

	private static PreparedQuery prepareWithoutOptimization(TupleExpr query) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		TupleExpr expression = new QueryRoot(query.clone());
		return new PreparedQuery(expression, strategy.precompile(expression));
	}

	private static void assertIndependentRows(List<BindingSet> actual, boolean entryBound) {
		assertThat(actual).hasSize(2);
		assertThat(actual).allSatisfy(row -> {
			assertThat(row.getValue("sibling")).isEqualTo(SIBLING_VALUE);
			assertThat(row.hasBinding("derivedFromSibling")).isFalse();
			if (entryBound) {
				assertThat(row.getValue("entry")).isEqualTo(CALLER_VALUE);
				assertThat(row.getValue("derived")).isEqualTo(CALLER_VALUE);
			} else {
				assertThat(row.hasBinding("derived")).isFalse();
			}
		});
		assertThat(actual.stream().map(row -> row.hasBinding("row")).toList())
				.containsExactlyInAnyOrder(true, false);
	}

	private static Join outerJoin(TupleExpr expression) {
		Join[] result = { null };
		expression.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				if (result[0] == null) {
					result[0] = join;
				}
				super.meet(join);
			}
		});
		assertThat(result[0]).as("the normal optimizer preserves an inner join").isNotNull();
		return result[0];
	}

	private static List<BindingSet> evaluate(PreparedQuery prepared, BindingSet input) {
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> results = prepared.step().evaluate(input)) {
			while (results.hasNext()) {
				rows.add(new QueryBindingSet(results.next()));
			}
		}
		return rows;
	}

	private record PreparedQuery(TupleExpr expression, QueryEvaluationStep step) {
	}
}
